def ptx_for(cc: int) -> tuple[str, bytes]:
    """挑选不超过设备算力的最高档 PTX；都没有则用最低档（PTX 向前兼容）。"""
    keys = sorted(int(k) for k in _PTX_B64)
    chosen = None
    for k in keys:
        if k <= cc:
            chosen = k
    if chosen is None:
        chosen = keys[0]
    key = str(chosen)
    return key, zlib.decompress(base64.b64decode(_PTX_B64[key]))
